    'account.deleteConfirm': 'Se borrarán tu cuenta y tus datos principales sincronizados, y se cerrará la sesión. Los datos guardados localmente en este navegador se conservarán. Algunos registros auxiliares de las funciones online no se borran automáticamente; puedes solicitar su eliminación escribiendo a danifloresgallegos0@gmail.com e indicando tu método de acceso y la información de perfil necesaria para localizar tu cuenta. Esta acción no se puede deshacer.',
