    'privacy.title': 'Política de privacidad',
    'privacy.body': '<p><strong>Datos locales.</strong> Sin iniciar sesión con Google o Discord, los mazos, tierlists, escenarios, favoritos, historial y ajustes que crees se guardan en este navegador. Si participas como invitado en un draft multijugador, Firebase crea una sesión anónima y procesa temporalmente los datos necesarios de la sala.</p><p><strong>Cuenta y sincronización.</strong> Si inicias sesión, tratamos el identificador, nombre y foto de tu cuenta, los datos de perfil que añadas y el contenido que sincronices. Si eliges Google, también tratamos el correo que Google facilita. Si eliges Discord, Discord procesa la autorización y nos facilita tu identificador, nombre visible y avatar; no solicitamos el correo de tu cuenta de Discord. Usamos estos datos para gestionar tu cuenta, mantenerlos disponibles entre dispositivos y prestar las funciones online. Tanto si accedes con Google como con Discord, la cuenta y los datos sincronizados se alojan en Google Firebase (Google Cloud).</p><p><strong>Seguridad.</strong> Firebase App Check usa reCAPTCHA v3 para prevenir fraude y abuso. Puede procesar datos técnicos y señales de interacción, como la dirección IP y datos del dispositivo o navegador, y usar la cookie de seguridad necesaria <strong>_GRECAPTCHA</strong>, incluso sin iniciar sesión.</p><p><strong>Sin analítica ni publicidad.</strong> No usamos Google Analytics ni analítica del comportamiento para medir cómo navegas. No mostramos publicidad, no creamos perfiles publicitarios y no vendemos tus datos. La evaluación de reCAPTCHA se utiliza únicamente para seguridad y prevención del abuso.</p><p><strong>Tus opciones.</strong> Desde «Mi perfil» puedes <strong>editar</strong> o <strong>descargar</strong> tus datos y <strong>borrar tu cuenta</strong>. El borrado automático elimina la cuenta y los datos principales sincronizados, pero conserva los datos locales de este navegador y no incluye todos los registros auxiliares de las funciones online. Para solicitar la eliminación de registros auxiliares asociados a tu cuenta, escribe a <a href="mailto:danifloresgallegos0@gmail.com">danifloresgallegos0@gmail.com</a> e indica tu método de acceso y la información de perfil necesaria para localizarla.</p><p>TCGmini es un proyecto de fans sin ánimo de lucro y no está afiliado a Nintendo, Creatures Inc., Game Freak ni The Pokémon Company.</p>',
