    'account.deleteConfirm': 'Your account and primary synced data will be deleted, and you will be signed out. Data stored locally in this browser will remain. Some auxiliary records created by online features are not deleted automatically; you can request their deletion by emailing danifloresgallegos0@gmail.com and providing your sign-in method and enough profile information to locate your account. This action cannot be undone.',
    'account.deleteSummary': 'Right now you have {decks} decks, {tiers} tier lists and {scenarios} scenarios.',
