    'account.deleted': 'Your account has been deleted.',
    'privacy.title': 'Privacy policy',
    'privacy.body': '<p><strong>Local data.</strong> Without signing in with Google or Discord, the decks, tier lists, scenarios, favorites, match history, and settings you create are stored in this browser. If you join a multiplayer draft as a guest, Firebase creates an anonymous session and temporarily processes the room data needed for that feature.</p><p><strong>Account and sync.</strong> If you sign in, we process your account identifier, name and photo, profile details you add, and content you choose to sync. If you choose Google, we also process the email address Google provides. If you choose Discord, Discord processes the authorization and provides us with your identifier, display name and avatar; we do not request your Discord email address. We use this information to manage your account, keep your data available across devices, and provide online features. Whether you use Google or Discord, the account and synced data are hosted on Google Firebase (Google Cloud).</p><p><strong>Security.</strong> Firebase App Check uses reCAPTCHA v3 to prevent fraud and abuse. It may process technical data and interaction signals, such as your IP address and device or browser information, and may set the necessary <strong>_GRECAPTCHA</strong> security cookie, even when you are not signed in.</p><p><strong>No analytics or advertising.</strong> We do not use Google Analytics or behavior analytics to measure how you browse the site. We do not display ads, build advertising profiles, or sell your data. reCAPTCHA risk assessment is used only for security and abuse prevention.</p><p><strong>Your choices.</strong> From “My profile”, you can <strong>edit</strong> or <strong>download</strong> your data and <strong>delete your account</strong>. Automatic deletion removes your account and primary synced data, but leaves data stored locally in this browser and does not cover every auxiliary record created by online features. To request deletion of auxiliary records linked to your account, email <a href="mailto:danifloresgallegos0@gmail.com">danifloresgallegos0@gmail.com</a> and provide your sign-in method and enough profile information to locate it.</p><p>TCGmini is a non-profit fan project and is not affiliated with Nintendo, Creatures Inc., Game Freak, or The Pokémon Company.</p>',
