    'privacy.title': 'プライバシーポリシー',
    'privacy.body': '<p><strong>ローカルデータ</strong>：GoogleまたはDiscordでログインしない場合、デッキ・ティアリスト・シーン・お気に入り・対戦履歴・設定は、このブラウザ内にのみ保存されます。ただし、マルチプレイドラフトにゲストとして参加すると、Firebase上に匿名セッションが作成され、ルームデータが一時的に処理されます。</p><p><strong>アカウントと同期</strong>：ログインすると、アカウントID・名前・写真、追加したプロフィール情報、同期対象のコンテンツを取り扱います。Googleを選んだ場合は、Googleから提供されるメールアドレスも取り扱います。Discordを選んだ場合は、Discordが認証を処理し、アカウントID・表示名・アバターを本サイトに提供します。Discordのメールアドレスは要求しません。これらの情報は、アカウント管理、端末間の同期、オンライン機能の提供に使用されます。GoogleとDiscordのどちらでログインしても、アカウントと同期データは<strong>Google Firebase</strong>（Google Cloud）に保存されます。</p><p><strong>セキュリティ</strong>：不正利用を防ぐため、Firebase App CheckはreCAPTCHA v3を使用します。その際、ログインしていない場合でも、IPアドレス、端末・ブラウザ情報、セキュリティシグナルが処理され、必須のセキュリティCookieである<code>_GRECAPTCHA</code>が設定されることがあります。</p><p><strong>解析・広告について</strong>：Google Analyticsを含むアクセス解析や行動分析は使用していません。広告の表示、広告配信用プロフィールの作成、データの販売も行いません。reCAPTCHAはセキュリティ目的にのみ使用します。</p><p><strong>データの管理</strong>：「プロフィール」から、データの<strong>編集</strong>・<strong>ダウンロード</strong>・<strong>アカウントの削除</strong>ができます。削除手続きを行うと、アカウントと主な同期データは自動的に削除されますが、このブラウザ内のローカルデータは残り、ゲーム関連の補助データがすべて削除されるとは限りません。補助データも削除する場合は、<a href="mailto:danifloresgallegos0@gmail.com">danifloresgallegos0@gmail.com</a>へ連絡し、ログイン方法とアカウントを特定するために必要なプロフィール情報をお知らせください。</p><p>本サイトは非営利のファンプロジェクトであり、任天堂・株式会社クリーチャーズ・株式会社ゲームフリーク・株式会社ポケモンとは一切関係ありません。</p>',
