    'privacy.title': 'Informativa sulla privacy',
    'privacy.body': '<p><strong>Dati locali.</strong> Se non accedi con Google o Discord, i tuoi mazzi, le tierlist, gli scenari, i preferiti, la cronologia delle partite e le impostazioni restano salvati nel tuo browser. Se partecipi a un draft multigiocatore come ospite, viene creata una sessione anonima Firebase e i dati della stanza vengono trattati temporaneamente per consentire lo svolgimento del draft.</p><p><strong>Account e sincronizzazione.</strong> Se accedi, trattiamo l’identificativo, il nome e la foto del tuo account, i dati del profilo che inserisci e i contenuti che scegli di sincronizzare. Se scegli Google, trattiamo anche l’indirizzo email fornito da Google. Se scegli Discord, Discord gestisce l’autorizzazione e ci fornisce il tuo identificativo, il nome visualizzato e l’avatar; non chiediamo l’indirizzo email del tuo account Discord. Questi dati servono a gestire l’account, sincronizzare i tuoi dispositivi e rendere disponibili le funzioni online. Con Google o Discord, l’account e i dati sincronizzati sono ospitati su <strong>Google Firebase</strong> (Google Cloud).</p><p><strong>Sicurezza.</strong> Per proteggere il servizio dagli abusi, Firebase App Check utilizza reCAPTCHA v3. Anche senza accedere, Google può trattare l’indirizzo IP, informazioni sul dispositivo e sul browser e segnali di sicurezza, e impostare il cookie di sicurezza necessario <code>_GRECAPTCHA</code>.</p><p><strong>Nessuna analisi comportamentale né pubblicità.</strong> Non utilizziamo Google Analytics né altri strumenti di analisi del comportamento; non mostriamo pubblicità, non creiamo profili pubblicitari e non vendiamo i tuoi dati. reCAPTCHA viene utilizzato esclusivamente per la sicurezza e la prevenzione degli abusi.</p><p><strong>Le tue opzioni.</strong> Da «Il mio profilo» puoi modificare o scaricare i tuoi dati ed eliminare il tuo account. La procedura automatica elimina l’account e i principali dati sincronizzati, ma non cancella i dati locali del browser né tutti i dati ausiliari legati alle funzioni di gioco. Per chiederne la cancellazione, scrivi a <a href="mailto:danifloresgallegos0@gmail.com">danifloresgallegos0@gmail.com</a> indicando il metodo di accesso e le informazioni del profilo necessarie a individuare l’account.</p><p>Questo sito è un progetto di fan senza scopo di lucro e non è affiliato a Nintendo, Creatures Inc., Game Freak o The Pokémon Company.</p>',
