    'account.deleteTitle': 'Supprimer le compte',
    'account.deleteConfirm': 'Ton compte et tes principales données synchronisées seront automatiquement supprimés, puis tu seras déconnecté. Les données locales de ce navigateur ne seront pas effacées. Certaines données auxiliaires liées aux fonctionnalités de jeu peuvent subsister : pour demander leur suppression, écris à danifloresgallegos0@gmail.com en indiquant ton mode de connexion et les informations de profil nécessaires pour retrouver ton compte. Cette action est irréversible.',
    'account.deleteSummary': 'Tu as actuellement {decks} decks, {tiers} tier lists et {scenarios} scénarios.',
    'account.deleteBtn': 'Supprimer le compte',
    'account.deleted': 'Ton compte a été supprimé.',
    'privacy.title': 'Politique de confidentialité',
    'privacy.body': '<p><strong>Données locales.</strong> Si tu ne te connectes pas avec Google ou Discord, tes decks, tierlists, scénarios, favoris, historique des parties et paramètres restent enregistrés dans ton navigateur. Si tu participes à un draft multijoueur en tant qu’invité, une session anonyme Firebase est créée et les données de la salle sont traitées temporairement afin de permettre le déroulement du draft.</p><p><strong>Compte et synchronisation.</strong> Si tu te connectes, nous traitons l’identifiant, le nom et la photo de ton compte, les informations de profil que tu renseignes et le contenu que tu choisis de synchroniser. Si tu choisis Google, nous traitons aussi l’adresse e-mail fournie par Google. Si tu choisis Discord, Discord traite l’autorisation et nous transmet ton identifiant, ton nom d’affichage et ton avatar ; nous ne demandons pas l’adresse e-mail de ton compte Discord. Ces données servent à gérer ton compte, à synchroniser tes appareils et à assurer les fonctionnalités en ligne. Avec Google comme avec Discord, le compte et les données synchronisées sont hébergés sur <strong>Google Firebase</strong> (Google Cloud).</p><p><strong>Sécurité.</strong> Pour protéger le service contre les abus, Firebase App Check utilise reCAPTCHA v3. Même sans connexion, Google peut traiter ton adresse IP, des informations sur ton appareil et ton navigateur ainsi que des signaux de sécurité, et déposer le cookie de sécurité nécessaire <code>_GRECAPTCHA</code>.</p><p><strong>Pas d’analyse comportementale ni de publicité.</strong> Nous n’utilisons ni Google Analytics ni aucun autre outil d’analyse du comportement ; nous n’affichons aucune publicité, ne créons aucun profil publicitaire et ne vendons pas tes données. reCAPTCHA est utilisé uniquement pour la sécurité et la prévention des abus.</p><p><strong>Tes options.</strong> Depuis « Mon profil », tu peux modifier ou télécharger tes données et supprimer ton compte. La procédure automatique supprime le compte et les principales données synchronisées, mais n’efface ni les données locales du navigateur ni l’ensemble des données auxiliaires liées aux fonctionnalités de jeu. Pour demander la suppression de ces dernières, écris à <a href="mailto:danifloresgallegos0@gmail.com">danifloresgallegos0@gmail.com</a> en indiquant ton mode de connexion et les informations de profil nécessaires pour retrouver le compte.</p><p>Ce site est un projet de fans à but non lucratif et n’est affilié ni à Nintendo, ni à Creatures Inc., ni à Game Freak, ni à The Pokémon Company.</p>',
