    'account.deleteConfirm': 'Sua conta e os principais dados sincronizados serão excluídos automaticamente, e sua sessão será encerrada. Os dados locais deste navegador não serão apagados. Alguns dados auxiliares ligados aos recursos de jogo podem permanecer: para solicitar a exclusão, escreva para danifloresgallegos0@gmail.com informando seu método de acesso e os dados de perfil necessários para localizar sua conta. Essa ação não pode ser desfeita.',
    'account.deleteSummary': 'Você tem no momento {decks} decks, {tiers} tier lists e {scenarios} cenários.',
    'account.deleteBtn': 'Excluir conta',
    'account.deleted': 'Sua conta foi excluída.',
    'privacy.title': 'Política de privacidade',
    'privacy.body': '<p><strong>Dados locais.</strong> Se você não fizer login com o Google ou o Discord, seus baralhos, tierlists, cenários, favoritos, histórico de partidas e ajustes ficam salvos no seu navegador. Se participar de um draft multijogador como convidado, uma sessão anônima do Firebase será criada e os dados da sala serão tratados temporariamente para permitir a realização do draft.</p><p><strong>Conta e sincronização.</strong> Se você fizer login, tratamos o identificador, o nome e a foto da sua conta, os dados de perfil que informar e o conteúdo que optar por sincronizar. Se escolher o Google, também tratamos o endereço de e-mail fornecido pelo Google. Se escolher o Discord, o Discord processa a autorização e nos fornece seu identificador, nome de exibição e avatar; não solicitamos o endereço de e-mail da sua conta do Discord. Esses dados são usados para gerenciar sua conta, sincronizar seus dispositivos e disponibilizar os recursos online. Com o Google ou o Discord, a conta e os dados sincronizados ficam hospedados no <strong>Google Firebase</strong> (Google Cloud).</p><p><strong>Segurança.</strong> Para proteger o serviço contra abusos, o Firebase App Check usa o reCAPTCHA v3. Mesmo sem fazer login, o Google pode tratar seu endereço IP, informações sobre o dispositivo e o navegador e sinais de segurança, além de gravar o cookie de segurança necessário <code>_GRECAPTCHA</code>.</p><p><strong>Sem análise comportamental nem publicidade.</strong> Não usamos o Google Analytics nem outras ferramentas de análise de comportamento; não exibimos anúncios, não criamos perfis publicitários e não vendemos seus dados. O reCAPTCHA é usado somente para segurança e prevenção de abusos.</p><p><strong>Suas opções.</strong> Em «Meu perfil», você pode editar ou baixar seus dados e excluir sua conta. O processo automático exclui a conta e os principais dados sincronizados, mas não apaga os dados locais do navegador nem todos os dados auxiliares ligados aos recursos de jogo. Para solicitar a exclusão desses dados, escreva para <a href="mailto:danifloresgallegos0@gmail.com">danifloresgallegos0@gmail.com</a> informando seu método de acesso e os dados de perfil necessários para localizar a conta.</p><p>Este site é um projeto de fãs sem fins lucrativos e não tem vínculo com a Nintendo, a Creatures Inc., a Game Freak nem com a The Pokémon Company.</p>',
