    'account.deleteConfirm': '계정과 주요 동기화 데이터(프로필, 덱, 티어표, 시나리오, 설정)가 자동으로 삭제되고 로그아웃됩니다. 이 브라우저의 로컬 데이터는 유지되며 게임 관련 부가 데이터가 모두 삭제되는 것은 아닙니다. 부가 데이터까지 삭제하려면 로그인 방법과 계정을 찾는 데 필요한 프로필 정보를 적어 danifloresgallegos0@gmail.com으로 요청해 주세요. 이 작업은 되돌릴 수 없습니다.',
