    'privacy.title': '개인정보 처리방침',
    'privacy.body': '<p><strong>로컬 데이터</strong>: Google 또는 Discord로 로그인하지 않으면 덱, 티어표, 시나리오, 즐겨찾기, 대전 기록과 설정은 이 브라우저에만 저장됩니다. 단, 멀티플레이 드래프트에 게스트로 참가하면 Firebase에 익명 세션이 생성되고 방 데이터가 일시적으로 처리됩니다.</p><p><strong>계정 및 동기화</strong>: 로그인하면 계정 식별자, 이름과 사진, 추가한 프로필 정보 및 동기화 대상 콘텐츠를 처리합니다. Google을 선택하면 Google에서 제공하는 이메일 주소도 처리합니다. Discord를 선택하면 Discord가 인증을 처리하고 계정 식별자, 표시 이름과 아바타를 제공합니다. Discord 계정의 이메일 주소는 요청하지 않습니다. 이 정보는 계정 관리, 기기 간 동기화 및 온라인 기능을 제공하는 데 사용됩니다. Google과 Discord 중 어느 방법으로 로그인해도 계정과 동기화 데이터는 <strong>Google Firebase</strong>(Google Cloud)에 저장됩니다.</p><p><strong>보안</strong>: 악용을 방지하기 위해 Firebase App Check는 reCAPTCHA v3를 사용합니다. 이 과정에서 로그인하지 않은 경우에도 IP 주소, 기기 및 브라우저 정보, 보안 신호가 처리될 수 있으며 필수 보안 쿠키인 <code>_GRECAPTCHA</code>가 설정될 수 있습니다.</p><p><strong>분석 및 광고</strong>: Google Analytics를 비롯한 웹 분석이나 이용 행태 분석 도구를 사용하지 않습니다. 광고를 게재하거나 광고용 프로필을 만들지 않으며 데이터를 판매하지도 않습니다. reCAPTCHA는 보안 목적으로만 사용합니다.</p><p><strong>데이터 관리</strong>: ‘내 프로필’에서 데이터를 <strong>수정</strong>하거나 <strong>다운로드</strong>하고 <strong>계정을 삭제</strong>할 수 있습니다. 계정 삭제 절차를 진행하면 계정과 주요 동기화 데이터는 자동으로 삭제되지만, 이 브라우저의 로컬 데이터는 유지되며 게임 관련 부가 데이터가 모두 삭제되는 것은 아닙니다. 부가 데이터까지 삭제하려면 로그인 방법과 계정을 찾는 데 필요한 프로필 정보를 적어 <a href="mailto:danifloresgallegos0@gmail.com">danifloresgallegos0@gmail.com</a>으로 요청해 주세요.</p><p>이 사이트는 비영리 팬 프로젝트이며 Nintendo, Creatures Inc., Game Freak, The Pokémon Company와 제휴하거나 관련이 없습니다.</p>',
